53	// capWarnings truncates a warning list to max entries, replacing the overflow
54	// with a single summary line so a systemic failure stays legible.
55	func capWarnings(warnings []string, max int) []string {
56		if len(warnings) <= max {
57			return warnings
58		}
59		extra := len(warnings) - max
60		out := append(warnings[:max:max], fmt.Sprintf("... and %d more warnings (suppressed)", extra))
61		return out
62	}
