64	// distillAgentRunner executes the seed agent with the distillation prompt for
65	// one transcript chunk and returns the agent's raw stdout. It is injected so
66	// the orchestration can be tested with a fake agent (the real implementation,
67	// execDistillAgent, shells out).
68	type distillAgentRunner func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error)
69	
70	// agentCallResult carries one prefetched distill-agent call result.
71	type agentCallResult struct {
72		out string
73		err error
74	}
75	
76	// chunkPrefetcher runs the distill agent over a session's chunks up to
77	// `concurrency` calls in flight ahead of the consumer. Results are delivered
78	// strictly in chunk order via result(i), so the consumer loop — parsing,
79	// reconciling, applying fact actions — keeps its exact serial semantics
80	// (reconcile mutates the branch fact store and must see chunks in order); only
81	// the agent round-trips overlap. stop() cancels unlaunched and in-flight calls;
82	// the per-chunk result channels are buffered so abandoned workers can deliver
83	// and exit without a reader.
84	type chunkPrefetcher struct {
85		results []chan agentCallResult
86		cancel  context.CancelFunc
87	}
88	
89	func startChunkPrefetch(ctx context.Context, run distillAgentRunner, dir string, args []string, chunks []transcriptChunk, timeout time.Duration, concurrency int) *chunkPrefetcher {
90		if concurrency < 1 {
91			concurrency = 1
92		}
93		pctx, cancel := context.WithCancel(ctx)
94		p := &chunkPrefetcher{results: make([]chan agentCallResult, len(chunks)), cancel: cancel}
95		for i := range p.results {
96			p.results[i] = make(chan agentCallResult, 1)
97		}
98		sem := make(chan struct{}, concurrency)
99		go func() {
100			for i := range chunks {
101				select {
102				case sem <- struct{}{}:
103				case <-pctx.Done():
104					p.results[i] <- agentCallResult{err: pctx.Err()}
105					continue
106				}
107				go func(i int) {
108					defer func() { <-sem }()
109					out, err := run(pctx, dir, args, []byte(chunks[i].Text), timeout)
110					p.results[i] <- agentCallResult{out: out, err: err}
111				}(i)
112			}
113		}()
114		return p
115	}
116	
117	// result blocks until chunk i's agent call completes and returns its output.
118	func (p *chunkPrefetcher) result(i int) (string, error) {
119		r := <-p.results[i]
120		return r.out, r.err
121	}
