298		if err != nil {
299			return nil, err
300		}
301		reconcileArgs, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, reconcilePrompt())
302		if err != nil {
303			return nil, err
304		}
305		// Pin the agent model + effort when set, so distill AND reconcile run on the same
306		// (cheap) model. Both are no-ops when empty.
307		args = injectAgentEffort(injectAgentModel(args, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
308		reconcileArgs = injectAgentEffort(injectAgentModel(reconcileArgs, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
309		threshold := distillOpts.confidenceThreshold
310		if threshold <= 0 {
311			threshold = defaultFactConfidenceThreshold
312		}
313	
314		sessions := append([]exportSession(nil), manifest.Sources.Sessions.Sessions...)
315		// Chronological order so any future supersession chain reconstructs
316		// deterministically regardless of incremental vs --force.
317		sort.SliceStable(sessions, func(i, j int) bool { return sessions[i].CreatedAt.Before(sessions[j].CreatedAt) })
318	
319		prevCache := loadDistillCache(brainDir)
320		newCache := distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(sessions))}
321	
322		byBranch := map[string][]factRecord{}
323		proposalsByBranch := map[string][]factProposal{}
324		loaded := map[string]bool{}
325		var warnings []string
326		chunksScanned, chunksDistilled := 0, 0
327	
328		// resolveBranch maps a session to the branch its facts are written under,
329		// falling back to the manifest default (then distillDefaultBranch) when the
330		// session's branch field is empty. The --branch filter must compare against
331		// this resolved value, not session.Branch, so sessions with an empty branch
332		// are not silently excluded from a `--branch <default>` run.
333		resolveBranch := func(session exportSession) string {
334			branch := session.Branch
335			if branch == "" {
336				branch = strings.TrimSpace(manifest.DefaultBranch)
337			}
338			if branch == "" {
339				branch = distillDefaultBranch
340			}
341			return branch
342		}
343	
344		// Denominator for progress: sessions that pass the branch filter. Cached
345		// (unchanged) sessions still advance the counter so the line reaches N/N.
346		totalSessions := 0
347		for _, session := range sessions {
348			if distillOpts.branch != "" && resolveBranch(session) != distillOpts.branch {
349				continue
350			}
351			totalSessions++
352		}
353		sessionsDone, factsFound := 0, 0
354		// Track agent-call outcomes so a misconfiguration that fails every call (e.g.
355		// an invalid --model) aborts fast with the agent's own error, instead of
356		// silently churning through every session reporting "0 facts found".
357		agentFailures, anyAgentSuccess := 0, false
358	
359		// ensureBranch lazily loads a branch's existing facts. On --force the
360		// previously distilled facts are dropped so they are rebuilt from scratch;
361		// authored facts are always preserved.
362		ensureBranch := func(branch string) {
363			if loaded[branch] {
364				return
365			}
366			existing, loadErr := loadFacts(brainDir, branch)
367			if loadErr != nil {
368				warnings = append(warnings, fmt.Sprintf("load facts for %s: %v", branch, loadErr))
369			}
370			if distillOpts.force {
371				kept := existing[:0]
372				for _, record := range existing {
373					if record.Origin != factOriginDistilled {
374						kept = append(kept, record)
375					}
376				}
377				existing = kept
378			}
379			byBranch[branch] = existing
380			loaded[branch] = true
381		}
382	
383		// flushFactStores persists the in-memory distill state — per-branch facts,
384		// proposals, and the session cache — so a killed or crashed run resumes from
385		// the last flush instead of losing everything (a distill run is hours of
386		// agent calls; the original write-once-at-the-end design lost the entire run
387		// on any interruption). Facts are idempotent across a resume: ids are
388		// content-derived and reconcile merges near-duplicates, so re-distilling the
389		// partially-flushed session at the kill point is safe. A mid-run (non-final)
390		// cache write keeps prevCache entries for sessions not yet visited — dropping
391		// manifest-removed sessions is the final write's job, and dropping unvisited
392		// entries mid-run would force a needless full re-distill of them after a
393		// restart.
394		flushFactStores := func(final bool) error {
395			for branch, records := range byBranch {
396				if err := writeFacts(brainDir, branch, records); err != nil {
397					return err
398				}
399				// Union this run's proposals with any already queued (a --force rebuild
400				// starts fresh since it rebuilds the distilled facts). Re-loading on
401				// every flush is idempotent: earlier flushes' proposals come back as
402				// priors and dedupe away.
403				var prior []factProposal
404				if !distillOpts.force {
405					if loadedProposals, loadErr := loadFactProposals(brainDir, branch); loadErr != nil {
406						warnings = append(warnings, fmt.Sprintf("load proposals for %s: %v", branch, loadErr))
407					} else {
408						prior = loadedProposals
409					}
410				}
411				merged := dedupeProposals(append(prior, proposalsByBranch[branch]...))
412				if err := writeFactProposals(brainDir, branch, merged); err != nil {
413					return err
414				}
415			}
416			cache := newCache
417			if !final {
418				cache = distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(prevCache.Sessions)+len(newCache.Sessions))}
419				for id, fingerprint := range prevCache.Sessions {
420					cache.Sessions[id] = fingerprint
421				}
422				for id, fingerprint := range newCache.Sessions {
423					cache.Sessions[id] = fingerprint
424				}
425			}
426			saveDistillCache(brainDir, cache)
427			return nil
428		}
429		flushInterval := distillOpts.flushEvery
430		if flushInterval <= 0 {
431			flushInterval = distillFlushCallInterval
432		}
433		callsSinceFlush := 0
434		maybeFlush := func() error {
435			if callsSinceFlush < flushInterval {
436				return nil
437			}
438			if err := flushFactStores(false); err != nil {
439				return err
440			}
441			callsSinceFlush = 0
442			return nil
443		}
444	
445		for _, session := range sessions {
446			branch := resolveBranch(session)
447			if distillOpts.branch != "" && branch != distillOpts.branch {
448				continue
449			}
450			ensureBranch(branch)
451	
452			sessionsDone++
453			// Report once per session, at every exit path, so the running fact count
454			// includes the session just processed (an emit at session start would lag
455			// by one session and always show 0 for a single-session run).
456			reportProgress := func() {
457				if distillOpts.progress != nil {
458					distillOpts.progress(distillProgress{SessionsDone: sessionsDone, SessionsTotal: totalSessions, Branch: branch, Facts: factsFound})
459				}
460			}
461	
462			// Read the transcript before the cache check so the fingerprint can hash
463			// the actual bytes: a re-export that rewrites the same path with different
464			// content (e.g. compact vs raw mode, or an exporter fix) under the same
465			// checkpoint must invalidate the cache and re-run the agent.
466			content, readErr := readBrainRelativeFile(brainDir, session.TranscriptPath)
467			if readErr != nil {
468				warnings = append(warnings, fmt.Sprintf("read transcript %s: %v", session.TranscriptPath, readErr))
469				reportProgress()
470				continue // not cached: retried next run
471			}
472	
473			// Strip tool calls/outputs and meta records up front: this is the actual
474			// input the agent distills (they carry no durable facts and dominate the
475			// transcript bytes, so removing them cuts chunk count — and agent calls —
476			// sharply). Blanked records keep their line slot so provenance anchors stay
477			// aligned to the original transcript. Fingerprinting this preprocessed input
478			// (not the raw bytes) means churn confined to stripped tool I/O no longer
479			// invalidates the cache and forces a needless re-distill.
480			distillInput := preprocessTranscriptForDistill(content)
481	
482			fingerprint := distillSessionFingerprint(session, branch, distillInput)
483			if !distillOpts.force {
484				if prev, ok := prevCache.Sessions[session.SessionID]; ok && prev == fingerprint {
485					newCache.Sessions[session.SessionID] = prev // unchanged; retain in cache and keep existing facts
486					reportProgress()
487					continue
488				}
489			}
490	
491			chunks := chunkTranscript(distillInput, distillOpts.maxChunkBytes)
492			// Agent calls for this session's chunks run up to `concurrency` in
493			// flight; results are consumed strictly in order below so reconcile and
494			// fact application keep their serial semantics.
495			prefetch := startChunkPrefetch(ctx, distillOpts.run, repoDir, args, chunks, distillOpts.timeout, distillOpts.concurrency)
496			sessionFailed := false
497			for chunkIdx, chunk := range chunks {
498				chunksScanned++
499				anchor := factAnchor{
500					SessionID:    session.SessionID,
501					CheckpointID: session.LatestCheckpoint,
502					Transcript:   filepath.ToSlash(session.TranscriptPath),
503					Line:         chunk.StartLine,
504				}
505				out, runErr := prefetch.result(chunkIdx)
506				callsSinceFlush++
507				if runErr != nil {
508					warnings = append(warnings, fmt.Sprintf("agent failed on %s:%d: %v", session.SessionID, chunk.StartLine, runErr))
509					sessionFailed = true
510					agentFailures++
511					// Fail fast on a misconfiguration: nothing has distilled yet and the
512					// agent keeps failing, so every call is almost certainly erroring the
513					// same way (bad --model, missing agent, auth). Abort with the agent's
514					// own error instead of churning through every remaining session.
515					if !anyAgentSuccess && agentFailures >= distillAgentAbortThreshold {
516						prefetch.stop()
517						return nil, fmt.Errorf("distill aborted after %d agent failures with no facts distilled — check --agent and --model. Last error: %v", agentFailures, runErr)
518					}
519					continue
520				}
521				anyAgentSuccess = true
522				records, chunkWarnings := distilledFactsFromOutput(out, taxonomy, anchor, branch, now)
523				warnings = append(warnings, chunkWarnings...)
524				if len(records) == 0 {
525					if err := maybeFlush(); err != nil {
526						prefetch.stop()
527						return nil, err
528					}
529					continue
530				}
531				factsFound += len(records)
532				chunksDistilled++
533				// Reconcile the chunk's candidates against the branch's active facts
534				// so near-duplicates merge and contradictions supersede instead of
535				// piling up. Low-confidence decisions are queued for review.
536				actions, recWarnings := reconcileChunkCandidates(ctx, distillOpts.run, reconcileArgs, records, byBranch[branch], repoDir, distillOpts.timeout)
537				warnings = append(warnings, recWarnings...)
538				callsSinceFlush++ // reconcile is an agent call too
539				var chunkProposals []factProposal
540				byBranch[branch], chunkProposals = applyFactActions(byBranch[branch], actions, threshold, now)
541				proposalsByBranch[branch] = append(proposalsByBranch[branch], chunkProposals...)
542				if err := maybeFlush(); err != nil {
543					prefetch.stop()
544					return nil, err
545				}
546			}
547			prefetch.stop()
548			// Only cache a session as distilled when every chunk succeeded, so a
549			// session whose agent calls failed is retried on the next run rather
550			// than being silently treated as done.
551			if !sessionFailed {
552				newCache.Sessions[session.SessionID] = fingerprint
553			}
554			reportProgress()
555		}
556	
557		warnings = capWarnings(warnings, maxDistillWarnings)
558	
559		if err := flushFactStores(true); err != nil {
560			return nil, err
561		}
562		if err := writeFactTaxonomy(brainDir, taxonomy); err != nil {
563			return nil, err
564		}
565	
566		// Summarize the manifest from the whole on-disk store, not just the branches
567		// touched this run. A branch-limited (`--branch`) or incremental run only
568		// loads a subset into byBranch; folding that subset into the manifest would
569		// drop counts/branches/proposals for facts that still exist on other
570		// branches. Re-reading the store after writing keeps sources.facts whole.
571		allBranches, err := loadAllFactBranches(brainDir)
572		if err != nil {
573			return nil, err
574		}
575		branchNames := make([]string, 0, len(allBranches))
576		for branch := range allBranches {
577			branchNames = append(branchNames, branch)
578		}
579		totalProposals := countFactProposals(brainDir, branchNames)
580	
581		source := summarizeFactSource(now, allBranches, chunksScanned, chunksDistilled, totalProposals, warnings)
582		if manifest.Sources == nil {
583			manifest.Sources = &brainSources{}
584		}
585		manifest.Sources.Facts = source
586		if manifest.GeneratedAt.IsZero() {
587			manifest.GeneratedAt = now
588		}
589		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
590			return nil, err
591		}
592		return source, nil
593	}
594	
595	// preprocessTranscriptForDistill strips tool calls and tool outputs (plus
596	// session/meta records) from a JSONL transcript before chunking, leaving only the
597	// human and assistant conversation text that the quality gate actually mines for
598	// facts. Each input line maps to exactly one output line: a dropped record
599	// becomes a blank line, which chunkTranscript skips while still incrementing the
600	// line counter, so a distilled fact's provenance anchor keeps pointing at the
601	// correct line in the original transcript. Lines that are not JSON objects (for
602	// example an already-rendered/compact transcript) are passed through unchanged so
603	// the preprocessor is safe for any transcript format.
604	func preprocessTranscriptForDistill(content string) string {
605		if doc, ok := distillDocumentConversation(content); ok {
606			return doc
607		}
608		lines := strings.Split(content, "\n")
609		for i, line := range lines {
610			if strings.TrimSpace(line) == "" {
611				lines[i] = ""
612				continue
613			}
614			var obj map[string]any
615			if err := json.Unmarshal([]byte(line), &obj); err != nil {
616				continue // not JSONL; leave the line as-is
617			}
618			// Collapse the kept text onto a single line so one record stays one line
619			// and the line numbering (provenance) is preserved.
620			lines[i] = strings.Join(strings.Fields(distillConversationText(obj)), " ")
621		}
622		return strings.Join(lines, "\n")
623	}
624	
625	// distillDocumentConversation handles transcripts exported as one pretty-printed
626	// JSON document (e.g. opencode sessions) rather than JSONL. The line-oriented
627	// preprocessor cannot strip these — every line of an indented document fails
628	// json.Unmarshal individually — so before this path existed they passed through
629	// *unstripped*, feeding megabytes of tool output, diffs, and token accounting to
630	// the distill agent (observed: a 22.6 MB opencode session was 1.3% conversation
631	// text, so the no-op strip cost ~75x the agent calls it should have).
632	//
633	// The document shape is {info, messages: [{info, parts: [{type, text, ...}]}]};
634	// only parts of type "text" are conversation (tool, patch, reasoning,
635	// step-start/finish, and file parts are mechanics). Output is one line per
636	// message — blank when the message has no conversation text — so a fact's
637	// provenance anchor line maps to the message index in the document, the closest
638	// analogue of the JSONL line mapping. ok=false when the content is not a
639	// document-form transcript, leaving the JSONL path to handle it.
640	func distillDocumentConversation(content string) (string, bool) {
641		trimmed := strings.TrimSpace(content)
642		if !strings.HasPrefix(trimmed, "{") {
643			return "", false
644		}
645		// A JSONL transcript has a complete JSON object on its first line; a
646		// pretty-printed document does not. Probe before paying the full parse.
647		firstLine, _, _ := strings.Cut(trimmed, "\n")
648		var probe map[string]any
649		if json.Unmarshal([]byte(firstLine), &probe) == nil {
650			return "", false
651		}
652		var doc struct {
653			Messages []struct {
654				Parts []map[string]any `json:"parts"`
655			} `json:"messages"`
656		}
657		if err := json.Unmarshal([]byte(trimmed), &doc); err != nil || len(doc.Messages) == 0 {
658			return "", false
659		}
660		lines := make([]string, len(doc.Messages))
661		for i, message := range doc.Messages {
662			var parts []string
663			for _, part := range message.Parts {
664				if jsonString(part["type"]) != "text" {
665					continue // tool, patch, reasoning, step-start/finish, file, ...
666				}
667				if text := jsonString(part["text"]); text != "" {
668					parts = append(parts, text)
669				}
670			}
671			// Collapse to a single line so one message stays one line (mirroring the
672			// JSONL path's record-per-line provenance contract).
673			lines[i] = strings.Join(strings.Fields(strings.Join(parts, " ")), " ")
674		}
675		return strings.Join(lines, "\n"), true
676	}
677	
678	// distillConversationText returns the human/assistant text worth distilling from
679	// one transcript record, or "" for tool calls, tool outputs, reasoning, and
680	// session/meta records. It mirrors the record routing in
681	// extractHistoryJSONFragments (codex `event_msg`/`response_item` and Claude
682	// `assistant`/`user` shapes) but deliberately keeps user turns — where standing
683	// rules and preferences live — and discards everything tool-related.
684	func distillConversationText(obj map[string]any) string {
685		switch jsonString(obj["type"]) {
686		case "agent_message":
687			return jsonString(obj["message"])
688		case "event_msg":
689			payload := jsonMap(obj["payload"])
690			switch jsonString(payload["type"]) {
691			case "agent_message", "user_message":
692				return jsonString(payload["message"])
693			case "task_complete":
694				return jsonString(payload["last_agent_message"])
695			}
696			return "" // task_started, exec_command_end, patch_apply_end, ...
697		case "response_item":
698			payload := jsonMap(obj["payload"])
699			if jsonString(payload["type"]) != "message" {
700				return "" // function_call, custom_tool_call, function_call_output, reasoning
701			}
702			if role := jsonString(payload["role"]); role != "assistant" && role != "user" {
703				return ""
704			}
705			return distillTextBlocks(payload["content"])
706		case "assistant", "user":
707			return distillTextBlocks(jsonMap(obj["message"])["content"])
708		case "message":
709			// pi sessions wrap every turn as {"type":"message","message":{role,content}}.
710			// Without this case they fell to the default branch, whose
711			// jsonString(obj["message"]) is "" for a map — silently stripping the
712			// ENTIRE session (observed: 13.4 MB pi transcript -> 0 bytes kept, so pi
713			// sessions contributed zero facts). Keep user/assistant text; the
714			// toolResult role and thinking/toolCall blocks are mechanics.
715			payload := jsonMap(obj["message"])
716			if role := jsonString(payload["role"]); role != "assistant" && role != "user" {
717				return "" // toolResult, ...
718			}
719			return distillTextBlocks(payload["content"])
720		case "session_meta", "turn_context", "permission-mode", "progress":
721			return ""
722		default:
723			return jsonString(obj["message"])
724		}
725	}
726	
727	// distillTextBlocks pulls plain text out of a message "content" field, keeping
728	// text blocks and dropping tool_use / tool_result blocks. content may be a plain
729	// string (a bare user/assistant message) or an array of typed blocks.
730	func distillTextBlocks(content any) string {
731		switch value := content.(type) {
732		case string:
733			return value
734		case []any:
735			var parts []string
736			for _, item := range value {
737				block := jsonMap(item)
738				if len(block) == 0 {
739					continue
740				}
741				switch jsonString(block["type"]) {
742				case "tool_use", "tool_result":
743					continue // tool call / tool output
744				default:
745					if text := firstNonEmptyString(block["text"], block["input_text"], block["output_text"], block["content"]); text != "" {
746						parts = append(parts, text)
747					}
748				}
749			}
750			return strings.Join(parts, " ")
751		default:
752			return ""
753		}
754	}
755	
756	// chunkTranscript splits a transcript into line-numbered chunks no larger than
757	// maxBytes (measured on the rendered, line-numbered text). A single line that
758	// exceeds maxBytes still becomes its own chunk rather than being dropped, so no
759	// content is silently lost. Blank input yields no chunks.
760	func chunkTranscript(content string, maxBytes int) []transcriptChunk {
761		return chunkLines(content, maxBytes, true)
762	}
763	
764	// chunkLines is the shared chunker behind chunkTranscript. numberLines controls
765	// the per-line rendering: distill wants the "<lineNo>\t" prefix so the agent can
766	// cite exact source lines, but the doc index wants clean text — the prefix would
767	// otherwise pollute the indexed text/embeddings and stop firstHeading from seeing
768	// markdown headings (a chunk would start "12\t## Title", not "## Title").
769	// Chunk StartLine/EndLine metadata is preserved either way.
770	func chunkLines(content string, maxBytes int, numberLines bool) []transcriptChunk {
771		if maxBytes <= 0 {
772			maxBytes = defaultDistillChunkSize
773		}
774		lines := strings.Split(content, "\n")
775		var chunks []transcriptChunk
776		var buf strings.Builder
777		startLine := 0
778		lineNo := 0
779		flush := func(endLine int) {
780			if buf.Len() == 0 {
781				return
782			}
783			chunks = append(chunks, transcriptChunk{StartLine: startLine, EndLine: endLine, Text: buf.String()})
784			buf.Reset()
785			startLine = 0
786		}
787		for _, line := range lines {
788			lineNo++
789			if strings.TrimSpace(line) == "" {
790				// Transcripts drop blank lines (noise) but keep counting for accurate
791				// line numbers. Docs preserve *internal* blank lines so markdown
792				// paragraph/code-block structure survives into the indexed text and
793				// embeddings; leading blanks (empty buffer) are skipped and trailing
794				// ones are trimmed by the caller (loadDocRecordsFromSeed). The blank is
795				// subject to the same size cap, so a run of blanks can't grow a chunk
796				// past maxBytes — it flushes at the boundary instead.
797				if !numberLines && buf.Len() > 0 {
798					if buf.Len()+1 > maxBytes {
799						flush(lineNo - 1)
800					} else {
801						buf.WriteString("\n")
802					}
803				}
804				continue
805			}
806			rendered := line + "\n"
807			if numberLines {
808				rendered = fmt.Sprintf("%d\t%s\n", lineNo, line)
809			}
810			if buf.Len() > 0 && buf.Len()+len(rendered) > maxBytes {
811				flush(lineNo - 1)
812			}
813			if buf.Len() == 0 {
814				startLine = lineNo
815			}
816			buf.WriteString(rendered)
817		}
818		flush(lineNo)
819		return chunks
820	}
821	
822	// distillSessionFingerprint is the incremental-skip signal for one session. It
823	// hashes the session identity (id, latest checkpoint, transcript path, resolved
824	// branch) together with a digest of the *preprocessed* distill input (tool I/O
825	// and meta records already stripped), so any change to what the agent actually
826	// distills — even one that keeps the same checkpoint, such as a compact↔raw
827	// re-export or an exporter fix — invalidates the cache and forces a re-distill,
828	// while churn confined to stripped tool I/O does not. The branch is the
829	// *resolved* one the facts are written under (session.Branch may be empty and
830	// fall back to the manifest default), so a default-branch change re-keys the
831	// session instead of letting a stale cache skip it.
832	func distillSessionFingerprint(session exportSession, branch, content string) string {
833		contentSum := sha256.Sum256([]byte(content))
834		sum := sha256.Sum256([]byte(strings.Join([]string{
835			session.SessionID,
836			session.LatestCheckpoint,
837			filepath.ToSlash(session.TranscriptPath),
838			branch,
839			hex.EncodeToString(contentSum[:]),
840		}, "\x00")))
841		return "sha256:" + hex.EncodeToString(sum[:])
842	}
