844	// readBrainRelativeFile reads a brain-relative path, rejecting absolute paths
845	// and parent-directory escapes so a manifest-supplied path cannot read outside
846	// the brain directory.
847	func readBrainRelativeFile(brainDir, rel string) (string, error) {
848		clean := filepath.Clean(filepath.FromSlash(rel))
849		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
850			return "", fmt.Errorf("unsafe transcript path: %s", rel)
851		}
852		data, err := os.ReadFile(filepath.Join(brainDir, clean))
853		if err != nil {
854			return "", err
855		}
856		return string(data), nil
857	}
858	
859	// loadDistillCache reads the incremental cache, always returning a usable value:
860	// any read/parse error or version mismatch yields an empty cache so the next
861	// run simply re-distills everything.
862	func loadDistillCache(brainDir string) distillCache {
863		empty := distillCache{Version: distillCacheVersion, Sessions: map[string]string{}}
864		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)))
865		if err != nil {
866			return empty
867		}
868		var cache distillCache
869		if err := json.Unmarshal(data, &cache); err != nil || cache.Version != distillCacheVersion || cache.Sessions == nil {
870			return empty
871		}
872		return cache
873	}
874	
875	// saveDistillCache persists the incremental cache. Failure is non-fatal: a
876	// missing cache only costs a full re-distillation next run.
877	func saveDistillCache(brainDir string, cache distillCache) {
878		data, err := json.MarshalIndent(cache, "", "  ")
879		if err != nil {
880			return
881		}
882		dir := filepath.Join(brainDir, factsDirName)
883		if err := os.MkdirAll(dir, 0o700); err != nil {
884			return
885		}
886		_ = writeFileAtomic(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)), append(data, '\n'), 0o600)
887	}
888	
889	// execDistillAgent is the real distillAgentRunner: it runs the agent with the
890	// transcript chunk on stdin and returns stdout, bounded by a timeout and an
891	// output-size cap.
892	func execDistillAgent(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
893		if len(args) == 0 {
894			return "", errors.New("distill: empty agent command")
895		}
896		runCtx, cancel := context.WithTimeout(ctx, timeout)
897		defer cancel()
898		command := exec.CommandContext(runCtx, args[0], args[1:]...)
899		command.Dir = dir
900		command.Stdin = bytes.NewReader(input)
901		var stdout, stderr bytes.Buffer
902		command.Stdout = &stdout
903		command.Stderr = &stderr
904		err := command.Run()
905		if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
906			return "", fmt.Errorf("agent timed out after %s", timeout)
907		}
908		if err != nil {
909			warning := strings.TrimSpace(stderr.String())
910			if warning == "" {
911				warning = strings.TrimSpace(stdout.String())
912			}
913			return "", fmt.Errorf("agent failed: %w: %s", err, truncateAgentWarning(warning))
914		}
915		if stdout.Len() > distillMaxOutputBytes {
916			return "", fmt.Errorf("agent output exceeds %d bytes", distillMaxOutputBytes)
917		}
918		return stdout.String(), nil
919	}
920

