	// flushes keep priors, and only the final flush of a COMPLETED rebuild
	// drops them in favor of the rebuilt proposals.
	backlog := []factProposal{{Action: "merge", CandidateID: "c1", TargetID: "t1", Confidence: 0.5, Branch: "main"}}
